  "settings.modelProvider.help.contextWindow": "سعة السياق التي يمكن للنموذج معالجتها دفعة واحدة، بالتوكنات. يستخدم ZAICODE هذا لإدارة السياق.\nلا تتجاوز الحد الفعلي للنموذج.",
