  "settings.modelProvider.help.inputModalities": "حدّد أنواع المحتوى التي يمكن للنموذج استلامها:\n\n- **نص**: يستقبل محتوى نصيًا. مطلوب.\n- **صور**: يستقبل محتوى صوريًا.\n- **فيديو**: يستقبل محتوى فيديو.\n- **PDF**: يستقبل مستندات PDF مباشرة.",
  "settings.modelProvider.help.outputModalities": "نوع ردود النموذج. يُدعم النص فقط حاليًا.",
  "settings.modelProvider.help.capabilities": "- **إخراج منظَّم**: يدعم قيود JSON Schema على حقول الإخراج وأنواعه وبنيته.\n- **بحث ويب أصلي**: يدعم خاصية البحث في الويب المدمجة في واجهة API للنموذج.\n- **رسائل نظام أثناء المحادثة**: يدعم إدراج تعليمات النظام أثناء المحادثة.\n\nلا تفعّل قدرات لا يدعمها النموذج.",
