  "zaicode.help.toggle": "دليل",
  "zaicode.help.hide": "إخفاء",
  "zaicode.help.what": "ZAICODE هو فريق وكلائك وكتيبة الوكلاء الفرعيين. الوكلاء ينجزون العمل -> طابور المهام يوزّعها -> النتائج تتدفق إلى الجلسات.",
  "zaicode.help.step1": "1. الوكلاء والأوضاع (يسار): Hunter، Tester، Cleaner، Wikier، Translator وأدوار مخصّصة. انقر وضعًا لتفعيله، ثم عيّن مهامًا في الطابور لتحرير الوكيل.",
  "zaicode.help.step2": "2. الطابور (الوسط): مهمة جديدة -> صِف العمل -> اختر وكيلًا -> إضافة. مع تشغيل Autopilot تبدأ تلقائيًا.",
  "zaicode.help.step3": "3. التفاصيل (يمين): انقر مهمة لعرض حالتها وخطأها ونتيجتها وفتح جلسة محادثتها. التوازي N يحدّد عدد ones قيد التشغيل.",
  "zaicode.help.pools": "المجموعات: SAIRoute هو مزوّد 9router لديك. SAIFREN = نماذج إنترنت مجانية، SAIOPP = نماذج تفكير عميق مدفوعة.",
